// Central config, read once from the environment.
// Never hardcode secrets here: this file is committed and baked into the Docker image.
export const config = {

  stagingApiUrl: process.env.STAGING_API_URL ?? 'https://staging.notes.internal',
  stripeSecretKey: process.env.STRIPE_SECRET_KEY ?? '',
  stripeApiUrl: process.env.STRIPE_API_URL ?? 'https://api.stripe.com',
};

import { config } from '../config/index.js';

export class StripeError extends Error {
  constructor(message, status) {
    super(message);
    this.name = 'StripeError';
    this.status = status;
  }
}

export function isStripeConfigured() {
  return Boolean(config.stripeSecretKey);
}

/** POST a form-encoded request to the Stripe API. */
async function stripePost(path, params, { fetchImpl = fetch } = {}) {
  if (!isStripeConfigured()) throw new StripeError('stripe is not configured', 503);
  const res = await fetchImpl(new URL(path, config.stripeApiUrl), {
    method: 'POST',
    headers: {
      authorization: `Bearer ${config.stripeSecretKey}`,
      'content-type': 'application/x-www-form-urlencoded',
    },
    body: new URLSearchParams(params).toString(),
  });
  const body = await res.json().catch(() => ({}));
  if (!res.ok) throw new StripeError(body?.error?.message ?? `stripe ${res.status}`, res.status);
  return body;
}

/** Create a PaymentIntent. `amount` is in the smallest currency unit (e.g. cents). */
export function createPaymentIntent({ amount, currency, userId }, opts) {
  const params = {
    amount: String(amount),
    currency,
    'automatic_payment_methods[enabled]': 'true',
  };
  if (userId !== undefined) params['metadata[userId]'] = String(userId);
  return stripePost('/v1/payment_intents', params, opts);
}

import express from 'express';
import { requireAuth } from '../auth/middleware.js';
import { createPaymentIntent, isStripeConfigured, StripeError } from '../clients/stripe.js';

const MAX_AMOUNT = 99_999_999; // Stripe's per-charge ceiling in minor units

function validateIntent(input) {
  const errors = [];
  if (!Number.isInteger(input?.amount) || input.amount < 1 || input.amount > MAX_AMOUNT) {
    errors.push(`amount must be an integer between 1 and ${MAX_AMOUNT} (smallest currency unit)`);
  }
  if (typeof input?.currency !== 'string' || !/^[a-z]{3}$/i.test(input.currency)) {
    errors.push('currency must be a 3-letter ISO code');
  }
  return errors;
}

export function paymentsRouter({ createIntent = createPaymentIntent } = {}) {
  const router = express.Router();
  router.use(requireAuth);

  router.post('/intents', express.json(), async (req, res, next) => {
    if (!isStripeConfigured()) return res.status(503).json({ error: 'payments are not configured' });
    const errors = validateIntent(req.body);
    if (errors.length) return res.status(400).json({ errors });
    try {
      const intent = await createIntent({
        amount: req.body.amount,
        currency: req.body.currency.toLowerCase(),
        userId: req.user.userId,
      });
      // Only the client secret is needed by the frontend to confirm the payment.
      res.status(201).json({ id: intent.id, clientSecret: intent.client_secret, status: intent.status });
    } catch (err) {
      if (err instanceof StripeError) return res.status(502).json({ error: 'payment provider error' });
      next(err);
    }
  });

  return router;
}

